	g += (vec2(texture(uNoise, p * 1.1 / 64.0 + t * 0.0055).g, texture(uNoise, p * 1.1 / 64.0 - t * 0.0047 + 0.5).g) - 0.5) * (0.12 + 0.1 * S);
